/**
 * FAQ Disclosure Widget
 * Handles expand/collapse behavior for FAQ items with proper accessibility
 */

document.addEventListener('DOMContentLoaded', () => {
  const buttons = document.querySelectorAll('button[aria-expanded]');

  // Initialize: collapse all panels on load
  buttons.forEach((btn) => {
    const panel = btn.closest('h3').nextElementSibling;
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;

    // Toggle panel on button click
    btn.addEventListener('click', () => {
      const isOpen = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!isOpen));
      panel.hidden = isOpen;
    });

    // Optional: Escape key closes the panel and returns focus to button
    btn.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
        btn.setAttribute('aria-expanded', 'false');
        panel.hidden = true;
        btn.focus();
      }
    });
  });
});

