+const { chromium } = require("playwright");
+const fs = require("fs");
+const path = require("path");
+
+async function runA11yTests() {
+  const browser = await chromium.launch();
+  const page = await browser.newPage();
+  
+  const htmlPath = path.join(__dirname, "index.html");
+  const htmlContent = fs.readFileSync(htmlPath, "utf8");
+  
+  await page.setContent(htmlContent, { waitUntil: "load" });
+  
+  // Load axe-core from node_modules
+  const axeSource = fs.readFileSync(
+    require.resolve("axe-core/axe.min.js"),
+    "utf8"
+  );
+  await page.evaluate((source) => {
+    eval(source);
+  }, axeSource);
+  
+  const results = await page.evaluate(async () => {
+    return await window.axe.run();
+  });
+  
+  await browser.close();
+  
+  // Separate WCAG violations from best-practice
+  const wcag = results.violations.filter(
+    (v) => !v.tags.includes("best-practice")
+  );
+  const bp = results.violations.filter((v) =>
+    v.tags.includes("best-practice")
+  );
+  
+  console.log(
+    JSON.stringify({
+      wcag: wcag.map((v) => ({
+        id: v.id,
+        impact: v.impact,
+        description: v.description,
+        targets: v.nodes.map((n) => n.target),
+      })),
+      bp: bp.map((v) => ({
+        id: v.id,
+        description: v.description,
+        targets: v.nodes.map((n) => n.target),
+      })),
+    }),
+    null,
+    2
+  );
+  
+  return wcag.length === 0;
+}
+
+runA11yTests()
+  .then((passed) => {
+    process.exit(passed ? 0 : 1);
+  })
+  .catch((err) => {
+    console.error("Test error:", err);
+    process.exit(1);
+  });
+
')

