.example {
  background: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}

.example:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
  transform: translateY(-2px);
}

.example h3 {
  margin: 0;
}

/* Button trigger */
.example button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.5rem;
  font-size: 1.1rem;
  font-weight: 600;
  text-align: left;
  background: white;
  border: none;
  cursor: pointer;
  color: #667eea;
  transition: all 0.3s ease;
  gap: 1rem;

  /* Focus indicator */
  outline: 2px solid transparent;
  outline-offset: -2px;
}

.example button:hover {
  background: #f8f9ff;
}

.example button:focus {
  outline: 2px solid #667eea;
  outline-offset: 2px;
}

/* Active/expanded state */
.example button[aria-expanded='true'] {
  background: #f0f3ff;
  color: #764ba2;
}

/* Toggle icon */
.example button::after {
  content: '';
  display: inline-block;
  width: 20px;
  height: 20px;
  background: linear-gradient(135deg, currentColor 48%, transparent 52%),
